def say(message):
    print(message, flush=True)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def encoded(value):
    return (json.dumps(value, ensure_ascii=False, indent=2) + '\n').encode('utf-8')


def beneath(base, path):
    result = Path(path).resolve()
    if not result.is_relative_to(base.resolve()):
        raise ValueError('Path escapes project/navigation directory: ' + str(path))
    return result


def asset(nav, relative):
    if not isinstance(relative, str) or '\\' in relative or ':' in relative:
        raise ValueError('Invalid relative navigation path: ' + repr(relative))
    p = PurePosixPath(relative)
    if p.is_absolute() or not p.parts or any(x in ('.', '..') for x in p.parts):
        raise ValueError('Unsafe relative navigation path: ' + relative)
    return beneath(nav, nav.joinpath(*p.parts))


def read(path, limit=32 * 1024 * 1024):
    if not path.is_file() or path.stat().st_size > limit:
        raise ValueError('Missing or oversized input: ' + str(path))
    data = path.read_bytes()
    if len(data) > limit:
        raise ValueError('Input grew beyond limit: ' + str(path))
    return data


def checked_entry(nav, entry, snapshots):
    path = asset(nav, entry['path'])
    data = read(path)
    if len(data) != entry['bytes'] or sha(data) != entry['sha256']:
        raise ValueError('Navigation integrity check failed: ' + str(path))
    snapshots[path] = data
    return path, data


def durable_new(path, data):
    with path.open('xb') as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())


def atomic_replace(path, data, expected=None):
    handle, temporary = tempfile.mkstemp(prefix='.bridge-fix-', suffix='.tmp', dir=path.parent)
    temporary = Path(temporary)
    try:
        with os.fdopen(handle, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        # Check after preparing the temporary file, immediately before replace.
        # This is an optimistic comparison followed by atomic replacement.
        if expected is not None and read(path) != expected:
            raise RuntimeError('Manifest changed before replacement; update refused: ' + str(path))
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def preflight(nav, raw, snapshots):
    if (raw.get('schema'), raw.get('kind'), raw.get('mmap_version')) != (1, 'adrive-ground-navmesh', 16):
        raise ValueError('Unsupported navigation manifest format')
    for category, expected in [('client', CLIENT), ('settings', SETTINGS)]:
        if any(raw.get(category, {}).get(key) != value for key, value in expected.items()):
            raise ValueError('Captured client/profile no longer matches: ' + category)
    tiles = {(t['c'], t['row'], t['col']): t for t in raw['tiles']}
    if len(tiles) != len(raw['tiles']) or not all(key in tiles for key in KEYS):
        raise ValueError('Duplicate or missing local navigation tiles')
    maps = [entry for entry in raw['maps'] if entry['c'] == 0]
    if len(maps) != 1 or maps[0]['sha256'] != MAP_SHA or maps[0]['bytes'] != 40:
        raise ValueError('Map-0 header no longer matches the verified case')
    library = raw['library']
    if library['sha256'] != DLL_SHA or library['bytes'] != 169472:
        raise ValueError('Active native DLL no longer matches the verified case')
    target = tiles[TARGET]
    if (target.get('mesh_x'), target.get('mesh_y')) != (11, 11):
        raise ValueError('Unexpected target mesh coordinates')
    if (target['sha256'], target['bytes']) not in [(OLD_SHA, OLD_BYTES), (NEW_SHA, NEW_BYTES)]:
        raise ValueError('Target tile contains an unknown change; nothing will be overwritten')
    # Validate every indexed path, but read only the active DLL, map 0 and 3x3 case.
    for entry in [*raw['maps'], *raw['tiles'], library]:
        asset(nav, entry['path'])
    dll_path, _ = checked_entry(nav, library, snapshots)
    _, map_data = checked_entry(nav, maps[0], snapshots)
    local = []
    for key in KEYS:
        _, data = checked_entry(nav, tiles[key], snapshots)
        local.append((key, data))
    return target, dll_path, map_data, local


def candidate_bytes():
    data = zlib.decompress(base64.b85decode(TILE_PAYLOAD_B85))
    if len(data) != NEW_BYTES or sha(data) != NEW_SHA:
        raise ValueError('Embedded candidate integrity check failed')
    header = struct.unpack_from('<4IB3B', data)
    mesh = struct.unpack_from('<15i', data, 20)
    if header != (0x4d4d4150, 7, 16, len(data)-20, 1, 0, 0, 0):
        raise ValueError('Unexpected candidate tile header')
    if mesh[:6] != (0x444e4156, 7, 11, 11, 0, 0) or mesh[13] != 0:
        raise ValueError('Unexpected candidate mesh/off-mesh header')
    profile = struct.unpack_from('<3f', data, 80)
    expected = (1.5999995470046997, .5333331823348999, .5333331823348999)
    if profile != expected:
        raise ValueError('Candidate agent profile differs from the original')
    return data


def native_verify(dll_path, map_data, local, candidate, report, loader):
    dll = loader(str(dll_path))
    ptr, ints = C.c_void_p, C.POINTER(C.c_int)
    floats, refs = C.POINTER(C.c_float), C.POINTER(C.c_uint64)
    cancel_type = C.CFUNCTYPE(C.c_int)
    specs = {
        'ad_create': ([ptr, C.c_int, C.POINTER(ptr)], C.c_int),
        'ad_destroy': ([ptr], None), 'ad_add': ([ptr, ptr, C.c_int], C.c_int),
        'ad_path': ([ptr, floats, floats, C.c_int, cancel_type, floats, refs, C.c_int, ints, ints], C.c_int),
    }
    for name, (args, result) in specs.items():
        fn = getattr(dll, name)
        fn.argtypes, fn.restype = args, result
    reason_fn = getattr(dll, 'ad_budget_reason', None)
    if reason_fn:
        reason_fn.argtypes, reason_fn.restype = [ptr, C.POINTER(C.c_uint32)], C.c_int
    report['native_queries'] = []
    for label, start, goal in [('A_to_B', A, B), ('B_to_A', B, A)]:
        say('验证原生短路线 ' + label + ' ...')
        handle = ptr()
        rc = dll.ad_create(map_data, len(map_data), C.byref(handle))
        if rc or not handle:
            raise RuntimeError('ad_create rc=' + str(rc))
        try:
            for key, data in local:
                data = candidate if key == TARGET else data
                rc = dll.ad_add(handle, data, len(data))
                if rc:
                    raise RuntimeError('ad_add ' + str(key) + ' rc=' + str(rc))
            cap = 65535
            output, polyrefs = (C.c_float * (cap * 3))(), (C.c_uint64 * cap)()
            count, expanded = C.c_int(), C.c_int()
            callback = cancel_type(lambda: 0)
            rc = dll.ad_path(handle, (C.c_float * 3)(*start), (C.c_float * 3)(*goal),
                             500000, callback, output, polyrefs, cap, C.byref(count), C.byref(expanded))
            row = dict(direction=label, rc=rc, expanded=expanded.value, point_count=count.value,
                       budget=500000, capacity=cap, guide=None, blocked_edges=[])
            report['native_queries'].append(row)
            if rc:
                if reason_fn:
                    status = C.c_uint32()
                    row['native_reason_code'] = reason_fn(handle, C.byref(status))
                    row['native_status'] = '0x%08x' % status.value
                raise RuntimeError('ad_path ' + label + ': ' + json.dumps(row, ensure_ascii=False))
            if not 2 <= count.value <= cap or not 0 <= expanded.value <= 4096:
                raise ValueError('Unexpected native count/expansion cost: ' + label)
            points = [list(output[3*i:3*i+3]) for i in range(count.value)]
            if not all(math.isfinite(v) for point in points for v in point):
                raise ValueError('Native path contains non-finite coordinates')
            for point, requested in [(points[0], start), (points[-1], goal)]:
                if any(abs(point[i] - C.c_float(requested[i]).value) > 1e-5 for i in (0, 1)):
                    raise ValueError('Native path relocated an XY endpoint: ' + label)
            length = sum(math.dist(a, b) for a, b in zip(points, points[1:]))
            closest = None
            for a, b in zip(points, points[1:]):
                dx, dy = b[0]-a[0], b[1]-a[1]
                den = dx*dx + dy*dy
                t = max(0.0, min(1.0, ((CENTER[0]-a[0])*dx + (CENTER[1]-a[1])*dy)/den)) if den else 0.0
                point = [a[i]+t*(b[i]-a[i]) for i in range(3)]
                distance = math.dist(point[:2], CENTER)
                if closest is None or distance < closest['distance_xy']:
                    closest = dict(distance_xy=distance, point=point)
            row.update(length_yards=length, points=points, bridge_crossing=closest,
                       endpoint_xy_only_float32_rounding=True)
            if not 40 <= length < 60 or closest['distance_xy'] > 3 or closest['point'][2] <= 27.5:
                raise ValueError('Native route did not meet short bridge-crossing gates: ' + label)
            say('  通过：%.4f 码，%d 个点，展开 %d 次' % (length, count.value, expanded.value))
        finally:
            dll.ad_destroy(handle)
    report['native_library_sha256'] = DLL_SHA
    report['native_validation_passed'] = True


def recheck(snapshots):
    for path, expected in snapshots.items():
        if read(path) != expected:
            raise RuntimeError('File changed during verification; active manifest untouched: ' + str(path))


def changed_manifest(before, relative_tile, record):
    after = copy.deepcopy(before)
    target = next(t for t in after['tiles'] if (t['c'], t['row'], t['col']) == TARGET)
    target.update(path=relative_tile, bytes=NEW_BYTES, sha256=NEW_SHA)
    after['identity'] = sha(json.dumps(after['tiles'], sort_keys=True).encode())[:16]
    if 'bytes' in after:
        if not isinstance(after['bytes'], int):
            raise ValueError('Unexpected manifest aggregate bytes')
        after['bytes'] += NEW_BYTES - OLD_BYTES
    repairs = after.setdefault('repairs', [])
    if not isinstance(repairs, list) or any(x.get('id') == REPAIR_ID for x in repairs if isinstance(x, dict)):
        raise ValueError('Existing repair metadata conflicts with this installer')
    repairs.append(record)
    return after


def current_record(raw):
    values = [x for x in raw.get('repairs', []) if isinstance(x, dict) and x.get('id') == REPAIR_ID]
    if len(values) != 1:
        raise ValueError('Active candidate lacks an unambiguous installer rollback record')
    return values[0]


def perform(root, report, report_path, rollback, loader):
    nav = beneath(root, root / 'data/navigation')
    manifest = beneath(nav, nav / 'manifest.json')
    before_bytes = read(manifest)
    raw = json.loads(before_bytes.decode('utf-8-sig'))
    snapshots = {manifest: before_bytes}
    say('阶段 1/3：核对版本、代理配置、DLL 与原始瓦片 ...')
    target, dll_path, map_data, local = preflight(nav, raw, snapshots)
    report.update(manifest=str(manifest), manifest_before_sha256=sha(before_bytes),
                  identity_before=raw['identity'], candidate_sha256=NEW_SHA)
    if rollback:
        if target['sha256'] == OLD_SHA:
            report['status'] = 'already_original'
            return
        record = current_record(raw)
        saved_before = read(asset(nav, record['manifest_before']))
        saved_after = read(asset(nav, record['manifest_after']))
        provenance = json.loads(read(asset(nav, record['provenance'])))
        if saved_after != before_bytes or sha(saved_before) != provenance['manifest_before_sha256']:
            raise ValueError('Current manifest has unrelated changes, or backup does not match; rollback refused')
        previous = json.loads(saved_before.decode('utf-8-sig'))
        if changed_manifest(previous, target['path'], record) != raw:
            raise ValueError('Backup does not reconstruct exactly this repair manifest')
        old_snapshots = {}
        old_target, _, _, _ = preflight(nav, previous, old_snapshots)
        if old_target['sha256'] != OLD_SHA:
            raise ValueError('Rollback backup does not reference the captured original tile')
        snapshots.update(old_snapshots)
        snapshots[asset(nav, record['manifest_before'])] = saved_before
        snapshots[asset(nav, record['manifest_after'])] = saved_after
        report['status'] = 'ready_to_rollback'
        atomic_replace(report_path, encoded(report))
        recheck(snapshots)
        atomic_replace(manifest, saved_before, expected=before_bytes)
        report.update(status='rolled_back', active_changed=True, identity_after=previous['identity'])
        return

    candidate = candidate_bytes()
    say('阶段 2/3：使用当前 DLL，在独立上下文中验证候选瓦片 ...')
    report['status'] = 'native_validation_in_progress'
    atomic_replace(report_path, encoded(report))
    native_verify(dll_path, map_data, local, candidate, report, loader)
    recheck(snapshots)
    if target['sha256'] == NEW_SHA:
        current_record(raw)
        report.update(status='already_installed_verified', identity_after=raw['identity'])
        return

    say('阶段 3/3：保存原始清单与修复记录，然后原子切换单个瓦片 ...')
    repairs_dir = beneath(nav, nav / 'repairs')
    repairs_dir.mkdir(exist_ok=True)
    repair_dir = repairs_dir / ('bridge-0000-50-34-' + report['attempt_id'])
    repair_dir.mkdir()
    prefix = repair_dir.relative_to(nav).as_posix() + '/'
    relative_tile = prefix + '0000_50_34.mmtile'
    record = dict(id=REPAIR_ID, tile=list(TARGET), provenance=prefix+'repair.json',
                  manifest_before=prefix+'manifest.before.json', manifest_after=prefix+'manifest.after.json')
    after = changed_manifest(raw, relative_tile, record)
    after_bytes = encoded(after)
    provenance = copy.deepcopy(REPAIR_NOTES)
    provenance.update(repair_id=REPAIR_ID, created_at_utc=report['started_at_utc'],
                      original_tile_record=target, candidate_sha256=NEW_SHA, candidate_bytes=NEW_BYTES,
                      manifest_before_sha256=sha(before_bytes), manifest_after_sha256=sha(after_bytes),
                      source_patch_file='RecastRasterization.change.patch',
                      native_validation=report['native_queries'], original_library_sha256=DLL_SHA,
                      identity_definition='sha256(json.dumps(manifest.tiles, sort_keys=True).encode())[:16]')
    durable_new(repair_dir/'0000_50_34.mmtile', candidate)
    durable_new(repair_dir/'manifest.before.json', before_bytes)
    durable_new(repair_dir/'manifest.after.json', after_bytes)
    durable_new(repair_dir/'RecastRasterization.change.patch', SOURCE_PATCH.encode())
    durable_new(repair_dir/'repair.json', encoded(provenance))
    snapshots[repair_dir/'0000_50_34.mmtile'] = candidate
    report.update(status='ready_to_install', repair_directory=str(repair_dir),
                  manifest_after_sha256=sha(after_bytes), identity_after=after['identity'])
    atomic_replace(report_path, encoded(report))
    recheck(snapshots)
    atomic_replace(manifest, after_bytes, expected=before_bytes)
    report.update(status='installed_verified', active_changed=True)


def run(root, rollback=False, *, _native_loader=None):
    """Internal loader injection exists only for offline tests; no CLI bypass."""
    root = Path(root).resolve()
    started = datetime.now(timezone.utc)
    attempt = started.strftime('%Y%m%dT%H%M%SZ') + '-' + uuid.uuid4().hex[:8]
    report = dict(version=VERSION, attempt_id=attempt, started_at_utc=started.isoformat(),
                  project_root=str(root), operation='rollback' if rollback else 'apply',
                  active_changed=False, native_validation_passed=False, status='started')
    report_path = None
    try:
        if not root.is_dir():
            raise ValueError('Project root does not exist')
        directory = beneath(root, root / 'runtime/bridge-fix-reports')
        directory.mkdir(parents=True, exist_ok=True)
        report_path = directory / (attempt + '.json')
        report['report_path'] = str(report_path)
        atomic_replace(report_path, encoded(report))
        say('诊断报告：' + str(report_path))
        perform(root, report, report_path, rollback, _native_loader or C.CDLL)
    except Exception as exc:
        report.update(status='failed', error=type(exc).__name__ + ': ' + str(exc))
        say('ERROR = ' + report['error'])
    report['finished_at_utc'] = datetime.now(timezone.utc).isoformat()
    if report_path:
        report['report_path'] = str(report_path)
        try:
            atomic_replace(report_path, encoded(report))
        except Exception as exc:
            report['report_write_error'] = type(exc).__name__ + ': ' + str(exc)
            say('无法写入完整报告：' + report['report_write_error'])
        say('REPORT = ' + str(report_path))
    return report


def main():
    say('BRIDGE FIX ' + VERSION + '：启动，正在准备校验。')
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--project-root', type=Path, default=Path.cwd())
    parser.add_argument('--rollback', action='store_true', help='Restore only the exact manifest saved by this repair.')
    args = parser.parse_args()
    if os.name != 'nt':
        parser.exit(1, 'This command is for the captured Windows installation.\n')
    report = run(args.project_root, args.rollback)
    if report['status'] == 'failed':
        say('未完成修复；请发送上面的 ERROR 和报告文件。')
        return 1
    if args.rollback:
        say('已恢复原始清单。' if report['active_changed'] else '当前已是原始瓦片，无需回滚。')
    else:
        say('修复已安装且双向原生验证通过。' if report['active_changed'] else '已安装同一修复；双向原生验证再次通过，未重写清单。')
        say('请重新启动客户端，再使用原来的 A/B 点。')
    return 0


